ALTER TABLE "User" ADD COLUMN "roleNames" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "rolesValidAfter" BIGINT NOT NULL DEFAULT 0;
UPDATE "User" u SET "roleNames"=ARRAY[r.name] FROM "Role" r WHERE r.id=u."roleId";
DELETE FROM "RolePermission" rp USING "Permission" p WHERE rp."permissionId"=p.id AND p.code='*';
